     1	import { connection } from "next/server";
     2	import { createClient } from "@/lib/supabase/server";
     3	import {
     4	  partition,
     5	  store,
     6	  REFRESH_MARGIN_MS,
     7	  TTL_MS,
     8	  type UrlCache,
     9	} from "./url-cache";
    10	
    11	/**
    12	 * Process-wide signed-URL cache.
    13	 *
    14	 * `createSignedUrls` returns a NEW token every call, so re-signing the same file
    15	 * yields a different URL — which the browser treats as a different image and
    16	 * re-downloads. Measured on the generator: switching occasion produced 3 of 3
    17	 * identical files and 0 of 3 identical URLs.
    18	 *
    19	 * Caching is safe because a signed URL is a capability for one path, and the
    20	 * caller has already had to obtain that path through RLS to ask for it. The
    21	 * cache grants nothing a caller could not mint for itself a line later.
    22	 */
    23	const cache: UrlCache = new Map();
    24	
    25	export async function signItemImages(paths: string[], expiresIn = 3600) {
    26	  const map = new Map<string, string>();
    27	  if (paths.length === 0) return map;
    28	
    29	  /**
    30	   * ⚠️ `Date.now()` is an unstable value, and under Cache Components Next
    31	   * refuses to prerender one — a clock read baked into a shell is frozen at
    32	   * build time and wrong for everyone after the first visitor. This function is
    33	   * request-time work by nature (it mints short-lived signed URLs), so saying
    34	   * so explicitly is the honest fix rather than a workaround.
    35	   *
    36	   * ⚠️ It did NOT show up in `npm run build`, only in the dev overlay.
    37	   */
    38	  await connection();
    39	  const now = Date.now();
    40	  const { fresh, stale } = partition(paths, cache, now, REFRESH_MARGIN_MS);
    41	  for (const [path, url] of fresh) map.set(path, url);
    42	  if (stale.length === 0) return map;
    43	
    44	  const supabase = await createClient();
    45	  const { data } = await supabase.storage.from("wardrobe").createSignedUrls(stale, expiresIn);
    46	
    47	  const minted = new Map<string, string>();
    48	  data?.forEach((d) => {
    49	    if (d.path && d.signedUrl) minted.set(d.path, d.signedUrl);
    50	  });
    51	
    52	  store(cache, minted, now, Math.min(TTL_MS, expiresIn * 1000));
    53	  for (const [path, url] of minted) map.set(path, url);
    54	  return map;
    55	}
    56	
    57	export function displayPath(item: { cutout_url: string | null; image_url: string }) {
    58	  return item.cutout_url ?? item.image_url;
    59	}

